abstract class ArtPiece{private static int c=1000;private final String pieceId;String title;ArtPiece(String t){title=t;pieceId="ART-"+(++c);}abstract String describe();String getPieceId(){return pieceId;}}class Painting extends ArtPiece{Painting(String t){super(t);}String describe(){return "Painting: "+title+", framed on canvas";}}class Sculpture extends ArtPiece{Sculpture(String t){super(t);}String describe(){return "Sculpture: "+title+", carved from stone";}}public class Main{public static void main(String[]a){}}